"""ISO week dates like 2026-W05-3."""

import re
from datetime import date


def parse_iso_week(text):
    """Return the date for an ISO week date string YYYY-Www-D."""
    # %W/%w are Monday-based/Sunday-based week numbers, not ISO 8601;
    # use date.fromisocalendar for true ISO week semantics.
    m = re.fullmatch(r"(\d{4})-W(\d{2})-([1-7])", text)
    if not m:
        raise ValueError(f"invalid ISO week date: {text!r}")
    year, week, day = map(int, m.groups())
    return date.fromisocalendar(year, week, day)

